package dev.aivillages.core.kernel.logistics;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import dev.aivillages.core.kernel.logistics.MobilityPolicy.*;
import static dev.aivillages.core.kernel.logistics.FollowState.*;
class FollowPolicyTest {
 final Actor actor=new Actor(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,2,"minecraft:overworld");
 Point p(double x){return new Point("minecraft:overworld",x,201,0);}
 FollowPolicy.Session session(){return FollowPolicy.start(UUID.randomUUID(),actor,p(0),p(12),10,5000,999);}
 FollowPolicy.Facts facts(long tick,Point feet,Point player,boolean connected){return new FollowPolicy.Facts(tick,actor,feet,actor.principal(),player,connected,true,true,true,false,5000,128,false);}
 @Test void maximumDeadlineAndTravelAreFinite(){var s=session();assertEquals(1210,s.goal().deadline());assertEquals(128,s.goal().travelCap());}
 @Test void initialHorizontalRangeAcceptsSixteenAndRefusesBeyond(){assertNotNull(FollowPolicy.start(UUID.randomUUID(),actor,p(0),p(16),10,20,1));assertThrows(IllegalArgumentException.class,()->FollowPolicy.start(UUID.randomUUID(),actor,p(0),p(16.001),10,20,1));}
 @Test void differentInitialDimensionIsRefused(){assertThrows(IllegalArgumentException.class,()->FollowPolicy.start(UUID.randomUUID(),actor,p(0),new Point("minecraft:the_nether",1,201,0),10,20,1));}
 @Test void invalidAllowancesAreRefused(){for(double n:new double[]{0,-1,Double.NaN,Double.POSITIVE_INFINITY})assertThrows(IllegalArgumentException.class,()->FollowPolicy.start(UUID.randomUUID(),actor,p(0),p(12),10,20,n));assertThrows(IllegalArgumentException.class,()->FollowPolicy.start(UUID.randomUUID(),actor,p(0),p(12),10,10,1));}
 @Test void moveProposalLookaheadIsAtMostEightBlocks(){var x=session().advance(facts(10,p(0),p(12),true));assertEquals(Action.MOVE_PROPOSAL,x.action());assertEquals(8,x.feet().distance(x.proposal()));}
 @Test void desiredBandWaitsAndStopsAtThreeBlocks(){for(double d:new double[]{1,2,3,4})assertEquals(Action.WAIT,session().advance(facts(10,p(0),p(d),true)).action());var x=session().advance(facts(10,p(0),p(6),true));assertEquals(3,x.proposal().distance(p(6)));}
 @Test void movingTargetObservationsAndRepathsRespectTenTicks(){var s=session();for(int t=10;t<40;t++)s.advance(facts(t,p(0),p(12+(t-10)*.2),true));assertEquals(3,s.state().observations());assertEquals(3,s.state().repaths());}
 @Test void insignificantPlayerMotionDoesNotRepath(){var s=session();for(int t=10;t<40;t++)s.advance(facts(t,p(0),p(12+(t-10)*.001),true));assertEquals(1,s.state().repaths());}
 @Test void duplicateTickIsInert(){var s=session();var first=s.advance(facts(10,p(0),p(12),true));assertSame(first,s.advance(facts(10,p(50),p(90),true)));assertEquals(0,s.state().traveled());}
 @Test void skippedOrBackwardsTicksStop(){var s=session();s.advance(facts(10,p(0),p(12),true));assertEquals(Reason.CLOCK_INVALID,s.advance(facts(12,p(0),p(12),true)).reason());var b=session();b.advance(facts(10,p(0),p(12),true));assertEquals(Reason.CLOCK_INVALID,b.advance(facts(9,p(0),p(12),true)).reason());}
 @Test void disconnectPausesImmediatelyAndResumePreservesSession(){var s=session();s.advance(facts(10,p(0),p(12),true));var id=s.state().session();var paused=s.advance(facts(11,p(.1),p(12),false));assertEquals(Reason.DISCONNECTED,paused.reason());s.advance(facts(12,p(.1),p(13),true));assertEquals(id,s.state().session());assertEquals(1,s.state().pausedTicks());assertEquals(.1,s.state().traveled());assertEquals(1210,s.state().deadline());}
 @Test void pauseLimitUsesOneHundredAccumulatedTicks(){var s=session();for(int t=10;t<109;t++)assertFalse(s.advance(facts(t,p(0),p(12),false)).terminal());assertEquals(Reason.PAUSE_LIMIT,s.advance(facts(109,p(0),p(12),false)).reason());}
 @Test void pausesConsumeOriginalElapsedAllowance(){var s=FollowPolicy.start(UUID.randomUUID(),actor,p(0),p(12),10,15,128);for(int t=10;t<=15;t++)s.advance(facts(t,p(0),p(12),false));assertEquals(Action.EXPIRED,s.state().action());assertEquals(Reason.DEADLINE,s.state().reason());}
 @Test void disjointPausesNeverResetPausedCount(){var s=session();for(int t=10;t<60;t++)s.advance(facts(t,p(0),p(12),false));s.advance(facts(60,p(0),p(3),true));for(int t=61;t<=110;t++)s.advance(facts(t,p(0),p(12),false));assertEquals(Reason.PAUSE_LIMIT,s.state().reason());assertEquals(100,s.state().pausedTicks());}
 @Test void tighterInheritedDeadlineNeverWidens(){var s=session();s.advance(new FollowPolicy.Facts(10,actor,p(0),actor.principal(),p(12),true,true,true,true,false,12,128,false));s.advance(facts(11,p(0),p(12),true));assertEquals(Reason.DEADLINE,s.advance(facts(12,p(0),p(12),true)).reason());}
 @Test void travelCounterAccumulatesAcrossPauseAndResume(){var s=session();s.advance(facts(10,p(0),p(12),true));s.advance(facts(11,p(1),p(12),false));s.advance(facts(12,p(2),p(12),true));assertEquals(2,s.state().traveled());}
 @Test void tighterTravelCapCannotWiden(){var s=session();s.advance(new FollowPolicy.Facts(10,actor,p(0),actor.principal(),p(12),true,true,true,true,false,5000,1,false));assertEquals(Reason.TRAVEL_LIMIT,s.advance(facts(11,p(1),p(12),true)).reason());}
 @Test void authorityRevocationAndCompetingOwnerStop(){for(boolean reserved:new boolean[]{false,true}){var x=session().advance(new FollowPolicy.Facts(10,actor,p(0),actor.principal(),p(12),true,true,true,reserved,reserved,5000,128,false));assertEquals(reserved?Reason.RESOURCE_RESERVED:Reason.UNAUTHORIZED,x.reason());}}
 @Test void wrongPlayerAndChangedGenerationStop(){assertEquals(Reason.IDENTITY_CHANGED,session().advance(new FollowPolicy.Facts(10,actor,p(0),UUID.randomUUID(),p(12),true,true,true,true,false,5000,128,false)).reason());var other=new Actor(actor.world(),actor.principal(),actor.citizen(),actor.entity(),2,2,actor.dimension());assertEquals(Reason.IDENTITY_CHANGED,session().advance(new FollowPolicy.Facts(10,other,p(0),actor.principal(),p(12),true,true,true,true,false,5000,128,false)).reason());}
 @Test void dimensionDeathAndUnloadedStop(){assertEquals(Reason.DIMENSION_CHANGED,session().advance(facts(10,p(0),new Point("minecraft:the_nether",1,201,0),true)).reason());assertEquals(Reason.DEAD,session().advance(new FollowPolicy.Facts(10,actor,p(0),actor.principal(),p(12),true,false,true,true,false,5000,128,false)).reason());assertEquals(Reason.UNLOADED,session().advance(new FollowPolicy.Facts(10,actor,p(0),actor.principal(),p(12),true,true,false,true,false,5000,128,false)).reason());}
 @Test void stopNeedsNoProviderAndCannotResume(){var s=session();var stop=s.stop(Reason.CANCELLED);assertSame(stop,s.advance(facts(10,p(0),p(12),true)));assertSame(stop,s.stop(Reason.UNAUTHORIZED));}
 @Test void restartCreatesNoAutomaticSessionOrRoute(){assertTrue(Arrays.stream(FollowPolicy.class.getDeclaredFields()).allMatch(f->java.lang.reflect.Modifier.isFinal(f.getModifiers())));assertThrows(IllegalArgumentException.class,()->new FollowPolicy.Goal(UUID.randomUUID(),actor,Long.MAX_VALUE,Long.MAX_VALUE,1));}
 @Test void noProgressStopsWithBoundedRepathWork(){var s=session();for(int t=10;t<=110;t++)s.advance(facts(t,p(0),p(12),true));assertEquals(Reason.NO_PROGRESS,s.state().reason());assertEquals(1,s.state().repaths());}
}
